<template><ForgeDialog title="File information" description="Inspect metadata and cryptographic hashes for a local file." eyebrow="WORKSPACE / FILES" wide @close="emit('close')"><div class="file-info-panel"><div class="file-pick"><input v-model="path" readonly placeholder="Choose a file" /><button class="action-button" :disabled="loading" @click="choose">Browse</button></div><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><div v-if="info" class="info-grid"><div><span>Size</span><b>{{ info.size }} bytes</b></div><div><span>Modified</span><code>{{ format(info.mtimeMs) }}</code></div><div><span>Created</span><code>{{ format(info.birthtimeMs) }}</code></div><div><span>Accessed</span><code>{{ format(info.atimeMs) }}</code></div><div v-for="(value,key) in hashes" :key="key" class="hash-row"><span>{{ key }}</span><code>{{ value || 'Unavailable' }}</code></div></div></div><template #footer><span class="website-help">Hashes are calculated locally and are never uploaded.</span><button class="action-button" :disabled="!path" @click="load">Refresh</button></template></ForgeDialog></template>
<script setup lang="ts">
import { ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { dialog, fs } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const path=ref(''); const info=ref<any>(); const hashes=ref<Record<string,string>>({}); const loading=ref(false); const error=ref(''); const algorithms=['md5','sha1','sha256','sha512','sha512Base64'] as const; const format=(value:number)=>value?new Date(value).toLocaleString():'—'; const choose=async()=>{const r=await dialog.showOpenDialog({properties:['openFile','showHiddenFiles']});if(!r.canceled&&r.filePaths[0]){path.value=r.filePaths[0];await load()}}; const load=async()=>{if(!path.value)return;loading.value=true;error.value='';try{info.value=await fs.stat(path.value);const values=await Promise.all(algorithms.map(async(type)=>[type,await fs.getFileHash(path.value,type)] as const));hashes.value=Object.fromEntries(values)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
</script>
<style scoped>.file-info-panel{display:grid;gap:14px}.file-pick{display:flex;gap:8px}.file-pick input{flex:1;min-width:0;padding:9px 10px;color:var(--pqt-text-muted);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px var(--pqt-font-mono)}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.info-grid>div{display:grid;gap:5px;padding:10px;border:1px solid var(--pqt-border);border-radius:7px}.info-grid span{color:var(--pqt-text-muted);font-size:10px;text-transform:uppercase}.info-grid code{overflow-wrap:anywhere;color:var(--pqt-text);font:10px var(--pqt-font-mono)}.hash-row{grid-column:1/-1}</style>
